from rich.console import Console
import os
import io

def main():
    r, w = os.pipe()
    # w is a file descriptor. os.fdopen(w, 'wb') returns a binary file.
    f_bin = os.fdopen(w, 'wb')
    f = io.TextIOWrapper(f_bin)

    console = Console(file=f)

    # Close the read end immediately to trigger BrokenPipeError on write
    os.close(r)

    try:
        for i in range(1000):
            console.print(f"Line {i}")
    except BrokenPipeError:
        print("Caught BrokenPipeError!")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    else:
        print(f"Finished without BrokenPipeError! quiet={console.quiet}")

if __name__ == "__main__":
    main()
